#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node* prev;
};

void pushBack(Node** headRef, int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    newNode->next = nullptr;
    if (*headRef == nullptr) {
        newNode->prev = nullptr;
        *headRef = newNode;
        return;
    }
    Node* last = *headRef;
    while (last->next != nullptr) {
        last = last->next;
    }
    last->next = newNode;
    newNode->prev = last;
}

void reverse(Node** headRef) {
    Node* current = *headRef;
    Node* temp = nullptr;
    while (current != nullptr) {
        temp = current->prev;
        current->prev = current->next;
        current->next = temp;
        current = current->prev;
    }
    if (temp != nullptr) {
        *headRef = temp->prev;
    }
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->next;
    }
    cout << endl;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = nullptr;
    pushBack(&head, 1);
    pushBack(&head, 2);
    pushBack(&head, 3);
    reverse(&head);
    printList(head);
    freeList(head);
    return 0;
}
